export function capitalize(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

// "action-button" -> "ActionButton"
export function pascalCase(name) {
  return name.split('-').map(capitalize).join('');
}

// A handful of playground-authored component slugs don't turn into their real
// @react-spectrum/s2 export name by a plain pascalCase — that export is what both
// resolves `deps/rsp/data/<Name>.json` (blocks/playground/playground.js) and drives
// the live esm.sh import (deps/rsp/playground/index.html). Not the same list as
// deps/impl-aliases.js: that one resolves which RSP *docs page* covers a slug (e.g.
// "select-box" -> "SelectBoxGroup", the family's docs page) and is auto-generated by
// deps/build-status-index.js — reusing it here would be wrong for a live single-component
// preview, which needs "select-box" -> "SelectBox" (already correct via plain pascalCase,
// no entry needed). This list is hand-maintained and specific to that one purpose.
const RSP_NAME_ALIASES = {
  cards: 'Card',
  'standard-dialog': 'Dialog',
  table: 'TableView',
};

export function resolveRspComponentName(name) {
  return RSP_NAME_ALIASES[name] ?? pascalCase(name);
}
